insert into public.role_features(role_id,feature_id) select r.id,f.id from public.roles r cross join public.feature_registry f where r.key='super_admin' on conflict do nothing;
insert into public.role_features(role_id,feature_id) select r.id,f.id from public.roles r join public.feature_registry f on f.key=any(case r.key when 'campus_admin' then array['feed','projects','jobs','events','hostel','food_delivery','notifications','profile','dashboard','admin','analytics','settings','directory'] when 'faculty' then array['feed','projects','jobs','events','profile','dashboard','settings','directory'] when 'student' then array['feed','marketplace','projects','jobs','events','hostel','food_delivery','chat','notifications','profile','dashboard','settings','directory'] when 'alumni' then array['feed','marketplace','projects','jobs','events','chat','notifications','profile','dashboard','settings','directory'] when 'vendor' then array['marketplace','food_delivery','profile','dashboard','settings'] when 'hostel_staff' then array['hostel','notifications','profile','dashboard','settings'] when 'moderator' then array['feed','marketplace','profile','dashboard','settings'] else array[]::text[] end) where r.key<>'super_admin' on conflict do nothing;
